package com.example.finance.data;
import android.content.Context; import android.os.Handler; import android.os.Looper; import androidx.annotation.NonNull; import androidx.room.Room; import androidx.room.migration.Migration; import androidx.sqlite.db.SupportSQLiteDatabase; import java.util.concurrent.*; import java.util.function.Consumer;
public class FinanceRepository { public final FinanceDao dao; private final ExecutorService executor=Executors.newSingleThreadExecutor(); private final Handler main=new Handler(Looper.getMainLooper());
 private static final Migration MIGRATION_1_2=new Migration(1,2) { @Override public void migrate(@NonNull SupportSQLiteDatabase db) {
  db.execSQL("ALTER TABLE accounts ADD COLUMN balance INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE accounts ADD COLUMN closed INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE accounts ADD COLUMN expiry TEXT NOT NULL DEFAULT ''");db.execSQL("ALTER TABLE operations ADD COLUMN appliedToBalance INTEGER NOT NULL DEFAULT 0");
  db.execSQL("CREATE TABLE IF NOT EXISTS account_movements (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, sourceId INTEGER, destinationId INTEGER, amount INTEGER NOT NULL, createdAt INTEGER NOT NULL, type TEXT NOT NULL, FOREIGN KEY(sourceId) REFERENCES accounts(id) ON UPDATE NO ACTION ON DELETE RESTRICT, FOREIGN KEY(destinationId) REFERENCES accounts(id) ON UPDATE NO ACTION ON DELETE RESTRICT)");db.execSQL("CREATE INDEX IF NOT EXISTS index_account_movements_sourceId ON account_movements (sourceId)");db.execSQL("CREATE INDEX IF NOT EXISTS index_account_movements_destinationId ON account_movements (destinationId)");
 }};
 public FinanceRepository(Context c){dao=Room.databaseBuilder(c.getApplicationContext(),FinanceDatabase.class,"finance.db").addMigrations(MIGRATION_1_2).build().dao();} public void run(Runnable task){executor.execute(task);} public void execute(Runnable task, Consumer<String> result){executor.execute(()->{String error=null;try{task.run();}catch(Exception e){error=e.getMessage()==null?"Не удалось сохранить изменения":e.getMessage();}String message=error;main.post(()->result.accept(message));});} }
